#!/bin/bash
# orca-6 (orca 6.0.0) on zeus:alon_q; generated by `rag-drg servers submit` from servers.yaml
#PBS -N H2O_sp
#PBS -q alon_q
#PBS -l select=1:ncpus=8:mpiprocs=8:mem=32gb
#PBS -l walltime=24:00:00
#PBS -j oe

WORKDIR="$PBS_O_WORKDIR"
JOBID="${PBS_JOBID%%.*}"
cd "$WORKDIR"

# --- orca-6: absolute paths, no environment modules ---
export PATH="/usr/local/orca-6.0.0:/usr/local/openmpi-4.1.1/bin:$PATH"
export LD_LIBRARY_PATH="/usr/local/orca-6.0.0:/usr/local/openmpi-4.1.1/lib:$LD_LIBRARY_PATH"
source /usr/local/orca6/setup.sh
source /usr/local/openmpi-4.1.1/setup.sh
ORCA_BIN=/usr/local/orca-6.0.0/orca

# --- per-job scratch ---
SCRATCH="/gtmp/$USER/$JOBID"
mkdir -p "$SCRATCH"

# on exit, also after a walltime kill or scancel/qdel/condor_rm (SIGTERM): copy back and clean up
cleanup() {
    # copy back everything useful, then clean scratch
    if cd "$SCRATCH" 2>/dev/null; then
        cp -f *.gbw *.hess *.xyz *.engrad *property.txt "$WORKDIR"/ 2>/dev/null
    fi
    cd "$WORKDIR" || true
    rm -rf "$SCRATCH"
}
trap cleanup EXIT
trap 'exit 143' TERM INT

INPUT="water.inp"
cp "$WORKDIR/water.inp" "$SCRATCH"/
# for MORead / InHess also copy: cp "$WORKDIR"/*.gbw "$WORKDIR"/*.hess "$SCRATCH"/ 2>/dev/null
cd "$SCRATCH"
"$ORCA_BIN" "$INPUT" > "$WORKDIR/water.out"
